from collections import deque
def comps(g,val=0):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            n=(y+dy,x+dx)
                            if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==val and n not in seen:
                                seen.add(n); q.append(n)
                out.append(cells)
    return out
